import XCTest
@testable import NextSetSyncCore

final class ImportTests: XCTestCase {
    /// Generated by NextSet's own generatePlan()/prescription() (nextset-strength 2f8651d).
    func testNextSetPrescription() throws {
        let ws = try WorkoutImporter.importFile(try Shared.data("fixtures/nextset-prescription.json"), fileName: "p.json")
        XCTAssertEqual(ws.count, 1)
        let w = ws[0]
        XCTAssertEqual(w.name, "Full Body A (week 3)")
        XCTAssertEqual(w.source, .nextset)
        XCTAssertEqual(w.exercises.first?.id, "goblet")
        XCTAssertEqual(w.exercises.first?.sets, 3)
        XCTAssertEqual(w.exercises.first?.reps, "8–12")
        XCTAssertEqual(w.exercises.first?.rest, 120)
        XCTAssertEqual(WireWorkout(w).ex.first?.reps, "8-12", "sent to the watch as ASCII")
    }

    func testNextSetPlanBecomesOneWorkoutPerSession() throws {
        let ws = try WorkoutImporter.importFile(try Shared.data("fixtures/nextset-plan.json"), fileName: "plan.json")
        XCTAssertEqual(ws.map(\.name), ["Full Body A", "Full Body B", "Full Body C"])
        XCTAssertEqual(ws[0].units, .lb)
        XCTAssertEqual(Set(ws.map(\.id)).count, 3)
    }

    func testNativeRoundTrip() throws {
        let data = try WorkoutImporter.exportData(Samples.fullBodyA)
        let back = try WorkoutImporter.importFile(data, fileName: "x.json")
        XCTAssertEqual(back.first?.exercises, Samples.fullBodyA.exercises)
        XCTAssertEqual(back.first?.source, .imported)
    }

    func testTextFormat() throws {
        let text = "# Leg day\nunits: kg\nBack squat, 3 x 5 @2, rest 180, 100\nLeg curl, 2 x 10-12, rest 60\nPlank\n"
        let w = try WorkoutImporter.importFile(Data(text.utf8), fileName: "legs.txt")[0]
        XCTAssertEqual(w.name, "Leg day"); XCTAssertEqual(w.units, .kg)
        XCTAssertEqual(w.exercises[0], WorkoutExercise(id: "back-squat", name: "Back squat", sets: 3, reps: "5", rir: 2, rest: 180, load: 100))
        XCTAssertEqual(w.exercises[1].reps, "10-12"); XCTAssertEqual(w.exercises[1].rest, 60)
        XCTAssertEqual(w.exercises[2].sets, 3)
    }

    func testRejectsBadFiles() {
        XCTAssertThrowsError(try WorkoutImporter.importFile(Data("{\"hello\":1}".utf8), fileName: "a.json"))
        XCTAssertThrowsError(try WorkoutImporter.importFile(Data([0xff, 0xfe, 0x00]), fileName: "a.bin"))
        var w = Samples.quickTest; w.exercises[0].sets = 11
        XCTAssertThrowsError(try w.validate())
    }
}

final class StoreTests: XCTestCase {
    func testBackupRoundTripAndRepeatedRestore() throws {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("backup-\(UUID())")
        defer { try? FileManager.default.removeItem(at: directory) }
        let store = try LocalStore(directory: directory)
        let now = Date(timeIntervalSince1970: 1_794_000_000)
        try store.saveWorkout(Samples.fullBodyA)
        let set = rec("set", rev: 2)
        var session = rec("s1", rev: 1); session.k = "ses"; session.n = 1
        var marker = rec("marker", rev: 3); marker.k = "mark"; marker.label = "Coffee"
        var deleted = marker; deleted.id = "deleted"; deleted.del = 1
        var checkin = rec("checkin", rev: 1); checkin.k = "chk"; checkin.score = 4
        let result = try store.upsert([set, session, marker, deleted, checkin], now: now)
        try store.markConfirmed(result.acks)
        try store.setNote("Sample note", for: marker.id)
        try store.recordZone(TimeZone(secondsFromGMT: 0)!, at: now)
        try store.updateLink { $0.key = "synthetic-pairing-key" }
        let sleep = SleepEntry(t10: 2_990_000, status: 2, consec: 1)
        let row = HealthRow(t10: sleep.t10, steps: 0, bpmMin: 56, bpmMax: 65, movement: 0, activity: 0)
        try store.importSleep([sleep], dataEndT10: sleep.t10 + 1)
        try store.importHealth([row])
        let data = try store.exportBackup()
        XCTAssertFalse(String(decoding: data, as: UTF8.self).contains("synthetic-pairing-key"))

        try store.eraseAll()
        XCTAssertTrue(store.sets.isEmpty)
        XCTAssertTrue(try store.restoreBackup(data))
        let reopened = try LocalStore(directory: directory)
        XCTAssertEqual(try reopened.exportBackup(), data)
        XCTAssertNil(reopened.link.key)
        XCTAssertFalse(try reopened.restoreBackup(data))
        XCTAssertEqual(try reopened.exportBackup(), data)
    }

    func testBackupMergesConflicts() throws {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("backup-\(UUID())")
        defer { try? FileManager.default.removeItem(at: directory) }
        let source = try LocalStore(directory: directory.appendingPathComponent("source"))
        let target = try LocalStore(directory: directory.appendingPathComponent("target"))
        try source.upsert([rec("newer", rev: 2), rec("local", rev: 1), rec("tie", rev: 1, reps: 6)])
        try target.upsert([rec("newer", rev: 1), rec("local", rev: 2), rec("tie", rev: 1, reps: 9)])
        try source.setNote("Older", for: "marker")
        try target.setNote("Local edit", for: "marker")
        try source.importSleep([SleepEntry(t10: 100, status: 2, consec: 1)], dataEndT10: 101)
        try target.importSleep([SleepEntry(t10: 100, status: 2, consec: 0)], dataEndT10: 102)
        try source.importHealth([HealthRow(t10: 100, steps: 0, bpmMin: 60, bpmMax: 66, movement: 0, activity: 0)])
        try target.importHealth([HealthRow(t10: 100, steps: 0, bpmMin: 63, bpmMax: 66, movement: 0, activity: 0)])

        let data = try source.exportBackup()
        XCTAssertTrue(try target.restoreBackup(data))
        XCTAssertFalse(try target.restoreBackup(data))
        XCTAssertEqual(target.sets.first { $0.id == "newer" }?.rev, 2)
        XCTAssertEqual(target.sets.first { $0.id == "local" }?.rev, 2)
        XCTAssertEqual(target.sets.first { $0.id == "tie" }?.reps, 9)
        XCTAssertEqual(target.note(for: "marker"), "Local edit")
        XCTAssertEqual(target.sleepEntries, source.sleepEntries)
        XCTAssertEqual(target.sleepDataEndT10, 102)
        XCTAssertEqual(target.healthRows, source.healthRows)
    }

    func rec(_ id: String, rev: Int, reps: Int = 8) -> WireRecord {
        WireRecord(k: "set", id: id, rev: rev, sid: "s1", wid: "w", wn: "Upper", xi: 0, xid: "bench", xn: "Bench", set: 1,
                   load: 135, units: "lb", reps: reps, rir: 2, at: 1_794_000_000_000, ed: nil, del: nil, start: nil, end: nil, n: nil)
    }

    func testUpsertRules() throws {
        let s = try LocalStore(directory: FileManager.default.temporaryDirectory.appendingPathComponent("st-\(UUID())"))
        var r = try s.upsert([rec("a", rev: 1), rec("b", rev: 1)])
        XCTAssertEqual(r.insertedSets, 2)
        r = try s.upsert([rec("a", rev: 1)])
        XCTAssertEqual(r.duplicates, 1)
        r = try s.upsert([rec("a", rev: 3, reps: 9)])
        XCTAssertEqual(r.updated, 1)
        r = try s.upsert([rec("a", rev: 2, reps: 1)])
        XCTAssertEqual(r.stale, 1)
        XCTAssertEqual(r.acks, [WireAck(id: "a", rev: 2)], "even a stale copy is acknowledged at its own rev")
        XCTAssertEqual(s.sets.first { $0.id == "a" }?.reps, 9)
        try s.markConfirmed([WireAck(id: "a", rev: 2)])
        XCTAssertEqual(s.sets.first { $0.id == "a" }?.ackState, .awaitingWatchAck, "ack of an older rev does not confirm rev 3")
        try s.markConfirmed([WireAck(id: "a", rev: 3)])
        XCTAssertEqual(s.sets.first { $0.id == "a" }?.ackState, .confirmed)
    }

    func testCSVKeepsNextSetColumnsAndBlocksFormulas() throws {
        let s = try LocalStore(directory: FileManager.default.temporaryDirectory.appendingPathComponent("csv-\(UUID())"))
        var bad = rec("x", rev: 1); bad.xn = "=HYPERLINK(\"http://e\")"; bad.wn = "Upper, \"A\""
        _ = try s.upsert([bad, rec("y", rev: 1)])
        var del = rec("z", rev: 2); del.del = 1
        _ = try s.upsert([del])
        let csv = SetCSV.make(s.sets, zone: TimeZone(identifier: "UTC")!)
        let lines = csv.components(separatedBy: "\r\n").filter { !$0.isEmpty }
        XCTAssertEqual(lines[0], (SetCSV.nextSetColumns + SetCSV.extraColumns).map { "\"\($0)\"" }.joined(separator: ","))
        XCTAssertTrue(lines[0].hasPrefix("\"date\",\"workout\",\"exercise\",\"set\",\"load\",\"units\",\"reps\",\"rir\",\"pain\""))
        XCTAssertEqual(lines.count, 3, "deleted set left out")
        XCTAssertTrue(csv.contains("\"'=HYPERLINK(\"\"http://e\"\")\""))
        XCTAssertTrue(csv.contains("\"Upper, \"\"A\"\"\""))
        XCTAssertTrue(lines[1].hasPrefix("\"2026-11-06\""), "1794000000 s is 2026-11-06 21:20 UTC")
        XCTAssertTrue(csv.contains("saved_on_phone_awaiting_watch_ack"))
    }

    func testZoneHistoryOnlyRecordsChanges() throws {
        let s = try LocalStore(directory: FileManager.default.temporaryDirectory.appendingPathComponent("z-\(UUID())"))
        try s.recordZone(TimeZone(identifier: "America/New_York")!, at: Date(timeIntervalSince1970: 0))
        try s.recordZone(TimeZone(identifier: "America/New_York")!, at: Date(timeIntervalSince1970: 100))
        try s.recordZone(TimeZone(identifier: "America/Denver")!, at: Date(timeIntervalSince1970: 200))
        XCTAssertEqual(s.zones.map(\.zone), ["America/New_York", "America/Denver"])
        let h = ZoneHistory(s.zones)
        XCTAssertEqual(h.zone(at: Date(timeIntervalSince1970: 150)).identifier, "America/New_York")
        XCTAssertEqual(h.zone(at: Date(timeIntervalSince1970: 250)).identifier, "America/Denver")
        XCTAssertEqual(h.zone(at: Date(timeIntervalSince1970: -5)).identifier, "America/New_York", "before the first mark")
    }

    func testWorkoutEditsBumpRevision() throws {
        let s = try LocalStore(directory: FileManager.default.temporaryDirectory.appendingPathComponent("w-\(UUID())"))
        try s.saveWorkout(Samples.fullBodyA)
        var w = Samples.fullBodyA; w.exercises[0].sets = 4
        try s.saveWorkout(w)
        XCTAssertEqual(s.workouts.first?.rev, 2)
        try s.saveWorkout(s.workouts[0])
        XCTAssertEqual(s.workouts.first?.rev, 2, "saving unchanged keeps the revision")
    }
}
